describe('Product List Display - Inventory Page', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should display all 6 product cards with complete details after login', () => {
    cy.get('[data-testid="user-name-input"]').type('standard_user');
    cy.get('[data-testid="password-input"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    cy.url().should('include', '/inventory.');
    cy.get('[data-testid="inventory-item"]').should('be.visible');
    cy.get('[data-testid="inventory-item"]').should('have.length', 6);

    cy.get('[data-testid="inventory-item"]').each(($item) => {
      cy.wrap($item).within(() => {
        cy.get('[data-testid="inventory-item-name"]').should('be.visible').should('not.have.length', 0);
        cy.get('[data-testid="inventory-item-price"]').should('be.visible').should('match', /^\$\d+\.\d{2}/);
      });
    });
  });

  it('should handle edge case when product list is empty or partially loaded', () => {
    cy.get('[data-testid="user-name-input"]').type('standard_user');
    cy.get('[data-testid="password-input"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    // Intercept the inventory API call and return an empty array
    cy.intercept('GET', '/api/inventory').as('getInventory');
    cy.wait('@getInventory');

    cy.get('[data-testid="inventory-item"]').should('not.exist');
    cy.get('[data-testid="empty-state-message"]').should('be.visible').should('contain', 'No products found');
  });
});
